def test_color_for_key_roygbiv_repeats_after_seven():
    # meridian: unit_id=db835681b862 requirement=2-3
    """Test that ROYGBIV sequence repeats after 7 keys."""
    keys = list(key_mapping._COLOR_BY_KEY.keys())
    
    if len(keys) >= 8:
        first_color = color_for_key(keys[0])
        eighth_color = color_for_key(keys[7])
