def test_color_for_key_sequence_boundaries():
    # meridian: unit_id=db835681b862 requirement=2-3
    """Test sequence boundaries: empty set, one element, many elements."""
    keys = list(key_mapping._COLOR_BY_KEY.keys())
    
    for i, key in enumerate(keys):
        result = color_for_key(key)
        assert isinstance(result, str)
        assert len(result) == 7
        
        if i >= 7:
            expected_color = color_for_key(keys[i - 7])
            assert result == expected_color


