def test_main_handles_key_press_and_highlights():
    # meridian: unit_id=28faeb62248a requirement=2-2
    """Test that pressing a mapped key triggers engine.key_down and draws highlight."""
    from tui import main
    
    mock_stdin = MagicMock()
    mock_stdin.fileno.return_value = 0
    mock_stdin.read.side_effect = ['a', 'q']
    
    with patch('tui.sys.stdin', mock_stdin), \
         patch('tui.termios.tcgetattr', return_value=[]), \
         patch('tui.termios.tcsetattr'), \
         patch('tui.tty.setcbreak'), \
         patch('tui.select.select', side_effect=[([mock_stdin], [], []), ([mock_stdin], [], [])]), \
         patch('tui.time.monotonic', return_value=1.0), \
         patch('tui.NoteEngine') as mock_engine_cls, \
         patch('tui._draw') as mock_draw, \
         patch('builtins.print'):
        
        mock_engine = Mock()
        mock_engine_cls.return_value = mock_engine
        
        captured_callback = None
        def capture_callback(on_state_change):
            nonlocal captured_callback
            captured_callback = on_state_change
            return mock_engine
        mock_engine_cls.side_effect = capture_callback
        
        main()
        
        # Verify engine.key_down was called for 'a' -> 'A'
        mock_engine.key_down.assert_called_with('A')
        
        # Verify the callback highlights the key
        assert captured_callback is not None
        captured_callback('A', True)
        assert any('A' in str(call_args) for call_args in mock_draw.call_args_list)


def test_main_removes_highlight_on_key_up():
    # meridian: unit_id=28faeb62248a requirement=2-2
    """Test that on_state_change callback removes highlight when key stops sounding."""
    from tui import main
    
    mock_stdin = MagicMock()
    mock_stdin.fileno.return_value = 0
    mock_stdin.read.return_value = 'q'
    
    with patch('tui.sys.stdin', mock_stdin), \
         patch('tui.termios.tcgetattr', return_value=[]), \
         patch('tui.termios.tcsetattr'), \
         patch('tui.tty.setcbreak'), \
         patch('tui.select.select', return_value=([mock_stdin], [], [])), \
         patch('tui.time.monotonic', return_value=1.0), \
         patch('tui.NoteEngine') as mock_engine_cls, \
         patch('tui._draw') as mock_draw, \
         patch('builtins.print'):
        
        mock_engine = Mock()
        captured_callback = None
        def capture_callback(on_state_change):
            nonlocal captured_callback
            captured_callback = on_state_change
            return mock_engine
        mock_engine_cls.side_effect = capture_callback
        
        main()
        
        # Simulate key becoming active then inactive
        captured_callback('A', True)
        active_call = mock_draw.call_args_list[-1][0][0]
        assert 'A' in active_call
        
        captured_callback('A', False)
        inactive_call = mock_draw.call_args_list[-1][0][0]
        assert 'A' not in inactive_call


