def test_main_cleans_up_in_finally():
    # meridian: unit_id=28faeb62248a requirement=2-2
    """Test that finally block restores terminal and closes engine."""
    from tui import main
    
    mock_stdin = MagicMock()
    mock_stdin.fileno.return_value = 0
    mock_stdin.read.return_value = 'q'
    saved_attrs = ['saved', 'termios', 'state']
    
    with patch('tui.sys.stdin', mock_stdin), \
         patch('tui.termios.tcgetattr', return_value=saved_attrs), \
         patch('tui.termios.tcsetattr') as mock_tcsetattr, \
         patch('tui.tty.setcbreak'), \
         patch('tui.select.select', return_value=([mock_stdin], [], [])), \
         patch('tui.time.monotonic', return_value=1.0), \
         patch('tui.NoteEngine') as mock_engine_cls, \
         patch('tui._draw'), \
         patch('builtins.print'):
        
        mock_engine = Mock()
        mock_engine_cls.return_value = mock_engine
        
        main()
        
        # Verify terminal state is restored
        mock_tcsetattr.assert_called_once()
        args = mock_tcsetattr.call_args[0]
        assert args[0] == 0  # fd
        assert args[2] == saved_attrs  # saved state
        
        # Verify engine is closed
        mock_engine.close.assert_called_once()


